// No personal contact channels are copied. Public sources provide the way in.
const CHECKED = '2026-11-04';

type Input = Omit<Person, 'community' | 'communityLead' | 'status' | 'sourceDate' | 'connections'>;

const person = (input: Input): Person => ({
  ...input,
  community: 'Wider ecosystem',
  communityLead: false,
  sourceDate: CHECKED,
  status: 'verified',
  connections: [
    { kind: 'get-help', label: `Ask about ${input.expertise[0]} or ${input.projects[0]}`, url: input.profileUrl ?? input.sourceUrl },
    { kind: 'offer-help', label: 'Offer a relevant collaboration or research question', url: input.sourceUrl },
    { kind: 'join-project', label: `Explore ${input.projects[0]} and public participation opportunities`, url: input.sourceUrl },
  ],
});

